 const pictureDayPanel=<section className="panel substandardDays"><div className="sectionHead"><div><span className="eyebrow">Picture footprint</span><h2>Pictures per BADS Category by Date</h2></div><small>Every picture recorded on each date, counted by category. Kept even after the full-size pictures are cleared.</small></div>{pictureDays.length?<div className="findingsTableWrap"><div className="dayTable"><div className="dayRow header">{[['day','Date and Time',false],['BUFFER','Buffer',true],['AISLE','Aisle',true],['DISPLAY','Display',true],['SHELF_TAG','Shelf Tag',true],['OTHER','Others',true],['total','Total',true],['notes','Notes',true]].map(([column,text,numeric])=><SortHead key={column} state={daySort} setState={setDaySort} column={column} text={text} numeric={numeric}/>)}</div>{sortedDays.map(entry=><div className="dayRow" key={entry.day}><span><strong>{fmt(entry.first)}</strong><small>{fmtTime(entry.first)}{entry.last!==entry.first?' – '+fmtTime(entry.last):''}</small></span>{['BUFFER','AISLE','DISPLAY','SHELF_TAG','OTHER'].map(category=><span className={'dayCount'+(entry.counts[category]?'':' zero')} key={category}>{entry.counts[category]||0}</span>)}<span className="dayCount"><b>{entry.total}</b></span><span className="footprintRemarks">{entry.notes.length?entry.notes.map(text=><em key={text}>{text}</em>):<em className="muted">—</em>}</span></div>)}</div></div>:<div className="analyticsEmpty">No pictures have been recorded for this store yet.</div>}</section>;
