 async function addComment(){if(!comment.trim())return;setBusy(true);try{await onComment(finding,comment);setTimeline(x=>[...x,{id:crypto.randomUUID(),description:comment,created_at:new Date().toISOString(),profiles:{full_name:user.full_name}}]);setComment('')}catch(e){notify(e.message,true)}finally{setBusy(false)}}
