 async function reloadFindings(){if(!supabase)return;let all=[],from=0;while(true){const{data,error}=await supabase.from('findings').select('*').eq('is_archived',false).order('created_at',{ascending:false}).range(from,from+999);if(error)throw error;all=all.concat(data||[]);if(!data||data.length<1000)break;from+=1000}setFindings(all)}
 async function reloadSubstandards(){if(!supabase)return;let all=[],from=0;try{while(true){const{data,error}=await supabase.from('substandard_findings').select('*').order('created_at',{ascending:false}).range(from,from+999);if(error)throw error;all=all.concat(data||[]);if(!data||data.length<1000)break;from+=1000}setSubstandards(all);setSubstandardReady(true)}catch(error){setSubstandards([]);setSubstandardReady(false)}}
 // Substandard only: 7 days after the record was created the full-size picture is cleared and the thumbnail kept
 async function purgeAgedSubstandardPhotos(rows){
  if(!supabase||user.role!=='regional_manager'||!online)return;
  const stamp='sn_substandard_purge_'+localDayKey(new Date());
  try{if(sessionStorage.getItem(stamp))return}catch{}
  const cutoff=Date.now()-SUBSTANDARD_PHOTO_TTL_DAYS*86400000,aged=(rows||[]).filter(row=>new Date(row.created_at).getTime()<cutoff).map(row=>row.id);
  try{
   let cleared=0;const listings=new Map();
   for(let i=0;i<aged.length;i+=100){
    const{data,error}=await supabase.from('substandard_photos').select('id,storage_path').in('substandard_id',aged.slice(i,i+100)).is('purged_at',null);
    if(error)throw error;
    for(const photo of data||[]){
     const path=String(photo.storage_path||''),cut=path.lastIndexOf('/');if(cut<0)continue;
     const dir=path.slice(0,cut),name=path.slice(cut+1);
     if(!listings.has(dir)){const{data:entries}=await supabase.storage.from('store-findings').list(dir,{limit:200});listings.set(dir,new Set((entries||[]).map(entry=>entry.name)))}
     if(!listings.get(dir).has(thumbPathFor(name)))continue;
     const{error:removeError}=await supabase.storage.from('store-findings').remove([path]);
     if(removeError)continue;
     const{error:markError}=await supabase.from('substandard_photos').update({purged_at:new Date().toISOString()}).eq('id',photo.id);
     if(markError)throw markError;
     signedCache.delete(path);cleared++;
    }
   }
   try{sessionStorage.setItem(stamp,'1')}catch{}
   if(cleared){persistSignedCache();notify(cleared+' full-size substandard picture'+(cleared===1?'':'s')+' older than '+SUBSTANDARD_PHOTO_TTL_DAYS+' days were cleared. Thumbnails, remarks and picture counts were kept.')}
  }catch{}
 }
 useEffect(()=>{if(substandardReady&&substandards.length)purgeAgedSubstandardPhotos(substandards)},[substandardReady,substandards.length,user.role,online]);
 async function saveSubstandard(form,photos){if(user.role!=='regional_manager')throw new Error('Only the Regional Manager can add substandard findings.');if(!online)throw new Error('An internet connection is required to save this record.');if(!photos.length)throw new Error('At least one evidence picture is required.');const payload={store_id:form.store_id,category:form.category,remark:form.remark.trim(),officers_on_duty:form.officers_on_duty.trim(),created_by:user.id};if(!supabase){const record={...payload,id:crypto.randomUUID(),status:'OPEN',created_at:new Date().toISOString()};setSubstandards(x=>[record,...x]);return}const{data:record,error}=await supabase.from('substandard_findings').insert(payload).select().single();if(error)throw error;for(const photo of photos){const path=form.store_id+'/substandard/'+substandardFolder(form.category)+'/'+record.id+'/'+crypto.randomUUID()+'.webp';const{error:uploadError}=await supabase.storage.from('store-findings').upload(path,photo.file,{contentType:'image/webp'});await uploadThumb(path,photo.file);if(uploadError)throw uploadError;const{error:photoError}=await supabase.from('substandard_photos').insert({substandard_id:record.id,uploaded_by:user.id,storage_path:path,file_size:photo.file.size});if(photoError)throw photoError}setSubstandards(x=>[record,...x])}
