 async function changeSubstandardStatus(item,status){const allowed=user.role==='store_manager'&&item.status==='OPEN'&&status==='DONE'||user.role==='regional_manager'&&item.status==='DONE'&&status==='OPEN';if(!allowed)throw new Error('This substandard action is not permitted for your role.');const patch=status==='DONE'?{status,resolved_at:new Date().toISOString(),resolved_by:user.id}:{status,resolved_at:null,resolved_by:null};const members=item._members&&item._members.length?item._members:[item],ids=members.filter(row=>status==='DONE'?row.status!=='DONE':row.status==='DONE').map(row=>row.id);if(!ids.length)return;let updated={...item,...patch};if(supabase){const{error}=await supabase.from('substandard_findings').update(patch).in('id',ids);if(error)throw error}updated={...item,...patch,_members:members.map(row=>ids.includes(row.id)?{...row,...patch}:row)};setSubstandards(x=>x.map(row=>ids.includes(row.id)?{...row,...patch}:row));setSelectedSubstandard(updated);notify(status==='DONE'?'Substandard finding marked Fixed / Done.':'Substandard finding reopened.')}
 async function updateSubstandard(form,newPhotos=[],removedPhotos=[]){if(user.role!=='regional_manager')throw new Error('Only the Regional Manager can edit substandard findings.');if(!online)throw new Error('An internet connection is required to update this record.');const target=selectedSubstandard,patch={category:form.category,remark:form.remark.trim(),officers_on_duty:form.officers_on_duty.trim()},mixedRemarks=(target._remarks||[]).length>1,groupPatch=mixedRemarks?{category:patch.category,officers_on_duty:patch.officers_on_duty}:patch;let updated={...target,...patch};if(supabase){const targetIds=substandardIds(target),{error}=await supabase.from('substandard_findings').update(groupPatch).in('id',targetIds);if(error)throw error;if(mixedRemarks){const{error:leadError}=await supabase.from('substandard_findings').update({remark:patch.remark}).eq('id',target.id);if(leadError)throw leadError}updated={...target,...patch,_members:(target._members||[]).map(row=>row.id===target.id?{...row,...patch}:{...row,...groupPatch})};for(const photo of newPhotos){const path=target.store_id+'/substandard/'+substandardFolder(form.category)+'/'+target.id+'/'+crypto.randomUUID()+'.webp';const{error:uploadError}=await supabase.storage.from('store-findings').upload(path,photo.file,{contentType:'image/webp'});await uploadThumb(path,photo.file);if(uploadError)throw uploadError;const{error:photoError}=await supabase.from('substandard_photos').insert({substandard_id:target.id,uploaded_by:user.id,storage_path:path,file_size:photo.file.size});if(photoError)throw photoError}if(removedPhotos.length){const ids=removedPhotos.map(photo=>photo.id),paths=removedPhotos.map(photo=>photo.storage_path);const{error:deleteError}=await supabase.from('substandard_photos').delete().in('id',ids);if(deleteError)throw deleteError;const{error:storageError}=await supabase.storage.from('store-findings').remove(withThumbs(paths));if(storageError)notify('Changes saved, but some removed picture files need manual storage cleanup.',true)}}updated={...updated,_photoVersion:Date.now()};const editedIds=substandardIds(target);setSubstandards(x=>x.map(row=>editedIds.includes(row.id)?(row.id===target.id?{...row,...patch}:{...row,...groupPatch}):row));setSelectedSubstandard(updated);notify('Substandard finding and pictures updated.')}
 async function deleteSubstandard(){if(user.role!=='regional_manager'){notify('Only the Regional Manager can delete substandard findings.',true);return}const target=selectedSubstandard,targetIds=substandardIds(target);if(!confirm('Permanently delete this substandard finding'+(targetIds.length>1?' ('+targetIds.length+' merged entries)':'')+', its pictures, and comments? This cannot be undone.'))return;try{if(supabase){const{data:photoRows,error:photoError}=await supabase.from('substandard_photos').select('storage_path').in('substandard_id',targetIds);if(photoError)throw photoError;const{data:deleted,error}=await supabase.from('substandard_findings').delete().in('id',targetIds).select('id');if(error)throw error;if(!deleted||!deleted.length)throw new Error('Delete was blocked. Run the latest substandard SQL in Supabase first.');const paths=(photoRows||[]).map(photo=>photo.storage_path);if(paths.length){const{error:storageError}=await supabase.storage.from('store-findings').remove(withThumbs(paths));if(storageError)notify('Record deleted, but some stored picture files need manual cleanup.',true)}}setSubstandards(x=>x.filter(row=>!targetIds.includes(row.id)));setSelectedSubstandard(null);setEditingSubstandard(false);notify('Substandard finding permanently deleted.')}catch(error){notify(error.message,true)}}
 async function saveFinding(form,photos){const permitted=user.role==='regional_manager'||user.role==='store_manager'&&stores.some(s=>s.id===form.store_id&&s.notes_entry_enabled);if(!permitted)throw new Error('Note entry is not activated for this store.');if(!online)throw new Error('You are offline. Your text draft is saved on this device.');if(!supabase){const st=stores.find(s=>s.id===form.store_id);const f={...form,id:crypto.randomUUID(),finding_no:(st?.store_code||'SN')+'-'+new Date().getFullYear()+'-'+String(findings.length+16).padStart(4,'0'),created_by:user.id,status:'OPEN',created_at:new Date().toISOString()};setFindings(x=>[f,...x]);notify('Finding created successfully.');return}const payload={...form,assigned_to:form.assigned_to||null,due_date:form.due_date||null,category_id:form.category_id||null,created_by:user.id};const{data:f,error}=await supabase.from('findings').insert(payload).select().single();if(error)throw error;for(let i=0;i<photos.length;i++){const p=photos[i],path=form.store_id+'/'+f.id+'/before/'+crypto.randomUUID()+'.webp';const{error:upErr}=await supabase.storage.from('store-findings').upload(path,p.file,{contentType:'image/webp'});await uploadThumb(path,p.file);if(upErr)throw upErr;await supabase.from('finding_photos').insert({finding_id:f.id,uploaded_by:user.id,storage_path:path,photo_type:'BEFORE',file_size:p.file.size})}setFindings(x=>[f,...x]);notify('Finding created successfully.')}
 async function updateFinding(form){if(user.role!=='regional_manager')throw new Error('Only the Regional Manager can edit findings.');const patch={store_id:form.store_id,assigned_to:form.assigned_to||null,category_id:form.category_id||null,priority:form.priority,title:form.title.trim(),description:form.description.trim(),due_date:form.due_date||null};let updated={...selected,...patch};if(supabase){const{data,error}=await supabase.from('findings').update(patch).eq('id',selected.id).select().single();if(error)throw error;updated=data}setFindings(x=>x.map(f=>f.id===updated.id?updated:f));setSelected(updated);notify('Finding updated successfully.')}
 async function deleteFinding(){if(user.role!=='regional_manager'){notify('Only the Regional Manager can delete findings.',true);return}if(!confirm('Permanently delete this finding, its comments, activity, and photos? This cannot be undone.'))return;try{const target=selected;if(supabase){const{data:photoRows,error:photoError}=await supabase.from('finding_photos').select('storage_path').eq('finding_id',target.id);if(photoError)throw photoError;const{data:deleted,error}=await supabase.from('findings').delete().eq('id',target.id).select('id').maybeSingle();if(error)throw error;if(!deleted)throw new Error('Delete was blocked. Run the latest workflow SQL in Supabase first.');const paths=(photoRows||[]).map(p=>p.storage_path);if(paths.length){const{error:storageError}=await supabase.storage.from('store-findings').remove(withThumbs(paths));if(storageError)notify('Finding deleted, but some stored photo files need manual cleanup.',true)}}setFindings(x=>x.filter(f=>f.id!==target.id));setSelected(null);setEditing(false);notify('Finding permanently deleted.')}catch(e){notify(e.message,true)}}
