 async function changeStatus(f,status){try{const allowed=user.role==='regional_manager'||user.role==='area_manager'&&f.status==='OPEN'&&status==='IN_PROGRESS'||user.role==='store_manager'&&f.status==='IN_PROGRESS'&&status==='FOR_VERIFICATION';if(!allowed)throw new Error('This workflow action is not permitted for your role.');if(supabase){const patch={status};if(status==='CLOSED')Object.assign(patch,{closed_at:new Date().toISOString(),closed_by:user.id,verified_at:new Date().toISOString(),verified_by:user.id});if(status!=='CLOSED'&&f.status==='CLOSED')Object.assign(patch,{closed_at:null,closed_by:null,verified_at:null,verified_by:null});const{error}=await supabase.from('findings').update(patch).eq('id',f.id);if(error)throw error}setFindings(x=>x.map(y=>y.id===f.id?{...y,status}:y));setSelected(x=>({...x,status}));notify(status==='CLOSED'?'Finding validated and marked Done.':status==='IN_PROGRESS'&&f.status==='OPEN'?'Finding acknowledged.':'Status updated.')}catch(e){notify(e.message,true)}}
