const STORE_SQL=`-- Store Notes Ver.2.0: synchronize the 31-store master list\ncreate temporary table store_notes_import(store_code text,store_name text,area text,area_manager text,remarks text) on commit drop;\ninsert into store_notes_import values\n${valuesSql};\nupdate public.stores s set store_code=i.store_code,area=i.area,district=i.area,is_active=true from store_notes_import i where lower(s.store_name)=lower(i.store_name);\ninsert into public.stores(store_code,store_name,area,district,is_active) select i.store_code,i.store_name,i.area,i.area,true from store_notes_import i where not exists(select 1 from public.stores s where lower(s.store_name)=lower(i.store_name));\nupdate public.stores set is_active=false where store_code not in(select store_code from store_notes_import);\n`;
